        LinearLayout forecast=panel();forecast.addView(label("АНАЛИТИКА ЗАРЯДКИ",10,BLUE,true));forecast.addView(infoLine("Скорость зарядки",chargingRate()));forecast.addView(infoLine("До 90%",forecastText(90)));forecast.addView(infoLine("До 100%",forecastText(100)));forecast.addView(infoLine("Текущая сессия",currentSessionText()));forecast.addView(label(slowChargeText(),12,batteryStatus==2&&isSlowCharging()?ORANGE:MUTED,false));content.addView(forecast);
        LinearLayout insight=panel();insight.addView(label("СЕЙЧАС",10,GREEN,true));insight.addView(label(advice(),15,TEXT,true));insight.addView(label("Показания обновляются автоматически при изменении состояния батареи.",12,MUTED,false));content.addView(insight);
