    View metric(String name,String value,String unit){LinearLayout c=panel();c.setPadding(dp(14),dp(14),dp(12),dp(14));TextView n=label(name.toUpperCase(Locale.ROOT),10,MUTED,true);TextView v=label(value,21,TEXT,true);TextView u=label(unit,10,MUTED,false);c.addView(n);LinearLayout rr=row();rr.addView(v);rr.addView(u);rr.setGravity(Gravity.BOTTOM);c.addView(rr);return c;}
    void historyPage(){LinearLayout p=panel();p.addView(label("История заряда",21,TEXT,true));p.addView(label("Выбери период для анализа",12,MUTED,false));LinearLayout periods=row();periods.setPadding(0,dp(12),0,dp(12));String[] ranges={"6 часов","24 часа","7 дней"};for(String range:ranges){TextView chip=label(range,11,chartPeriod.equals(range)?0xff09130f:MUTED,true);chip.setGravity(Gravity.CENTER);chip.setPadding(dp(10),dp(9),dp(10),dp(9));chip.setBackground(shape(chartPeriod.equals(range)?GREEN:PANEL2,14,0));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(dp(3),0,dp(3),0);periods.addView(chip,cp);chip.setOnClickListener(v->{chartPeriod=range;buildPage();});}p.addView(periods);
        LinearLayout metrics=row();metrics.setPadding(0,0,0,dp(8));String[] metricNames={"Заряд","Температура","Ток","Напряжение"};for(String metricName:metricNames){TextView chip=label(metricName,10,chartMetric.equals(metricName)?0xff09130f:MUTED,true);chip.setGravity(Gravity.CENTER);chip.setPadding(dp(7),dp(9),dp(7),dp(9));chip.setBackground(shape(chartMetric.equals(metricName)?BLUE:PANEL2,12,0));LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(0,-2,1);mp.setMargins(dp(2),0,dp(2),0);metrics.addView(chip,mp);chip.setOnClickListener(v->{chartMetric=metricName;buildPage();});}p.addView(metrics);p.addView(new HistoryChart(),new LinearLayout.LayoutParams(-1,dp(190)));content.addView(p);LinearLayout stats=panel();stats.addView(label("АРХИВ ИЗМЕРЕНИЙ",10,MUTED,true));stats.addView(label(String.valueOf(history.size()),28,TEXT,true));stats.addView(label("До 7 дней локальной истории · замеры примерно раз в минуту",12,MUTED,false));stats.addView(infoLine("Первый замер",firstSampleTime()));stats.addView(infoLine("Последний замер",lastSampleTime()));content.addView(stats);
        LinearLayout analytics=panel();analytics.addView(label("АНАЛИТИКА ЗАРЯДКИ",16,TEXT,true));analytics.addView(infoLine("Зарядных сессий в архиве",String.valueOf(chargeSessions())));analytics.addView(infoLine("Средняя температура",averageTemp()));analytics.addView(infoLine("Оценка скорости зарядки",chargingRate()));analytics.addView(infoLine("Текущая сессия",currentSessionText()));content.addView(analytics);LinearLayout sessions=panel();sessions.addView(label("ПОСЛЕДНИЕ СЕССИИ",16,TEXT,true));addSessionRows(sessions);content.addView(sessions);
        LinearLayout thermal=panel();thermal.addView(label("ТЕМПЕРАТУРА",14,TEXT,true));thermal.addView(new TemperatureChart(),new LinearLayout.LayoutParams(-1,dp(110)));content.addView(thermal);
        TextView export=label("Поделиться историей",14,BLUE,true);export.setPadding(dp(5),dp(12),0,dp(12));export.setOnClickListener(v->shareHistory());content.addView(export);TextView clear=label("Очистить историю",14,RED,true);clear.setPadding(dp(5),dp(12),0,dp(12));clear.setOnClickListener(v->{history.clear();sampleTimes.clear();sampleTemps.clear();sampleCurrents.clear();sampleVoltages.clear();sampleStatuses.clear();saveHistory();buildPage();});content.addView(clear);}
    void healthPage(){LinearLayout p=panel();p.addView(label("Состояние аккумулятора",21,TEXT,true));p.addView(label(healthText(),17,GREEN,true));p.addView(label("Android сообщает системный статус батареи. Это не лабораторная диагностика ёмкости.",12,MUTED,false));content.addView(p);LinearLayout grid=panel();grid.addView(infoLine("Системное здоровье",healthText()));grid.addView(infoLine("Температура",tempText()));grid.addView(infoLine("Технология",techText()));grid.addView(infoLine("Циклы зарядки",cycleText()));grid.addView(infoLine("Оценка износа","Недоступна без проектной ёмкости"));content.addView(grid);LinearLayout note=panel();note.addView(label("Почему нет процента износа?",16,TEXT,true));note.addView(label("Стандартный Android API не гарантирует доступ к заводской ёмкости батареи. Поэтому приложение не подменяет реальное измерение случайным процентом. На некоторых моделях доступны дополнительные данные производителя.",12,MUTED,false));content.addView(note);}
    View infoLine(String a,String b){LinearLayout r=row();TextView x=label(a,13,MUTED,false);TextView y=label(b,13,TEXT,true);r.addView(x,new LinearLayout.LayoutParams(0,-2,1));r.addView(y);View line=new View(this);line.setBackgroundColor(0xff293342);LinearLayout wrap=column();wrap.addView(r);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(1));lp.topMargin=dp(12);lp.bottomMargin=dp(12);wrap.addView(line,lp);return wrap;}
