        LinearLayout top=row();top.setGravity(Gravity.CENTER_VERTICAL);
        BatteryRing bigRing=new BatteryRing();top.addView(bigRing,new LinearLayout.LayoutParams(dp(116),dp(116)));
        LinearLayout details=column();LinearLayout.LayoutParams dl=new LinearLayout.LayoutParams(0,-2,1);dl.leftMargin=dp(18);top.addView(details,dl);
