        addSmartInsights();addAlertSettings();
        LinearLayout thermal=panel();thermal.addView(label("ТЕРМОКОНТРОЛЬ",10,ORANGE,true));
        thermal.addView(infoLine("Состояние температуры",thermalStatus()));
