        content.addView(checks);
        LinearLayout report=panel();report.addView(label("ОТЧЁТ BATTERY MONITOR 42",16,TEXT,true));
        report.addView(label("Сводка включает показатели телефона, статистику разряда, температурные события и историю измерений.",12,MUTED,false));
        TextView share=label("Экспортировать полный отчёт  ↗",14,BLUE,true);share.setPadding(0,dp(15),0,dp(5));share.setOnClickListener(v->shareFullReport());report.addView(share);
        TextView historyExport=label("Экспортировать историю измерений",13,MUTED,true);historyExport.setPadding(0,dp(10),0,dp(3));historyExport.setOnClickListener(v->shareHistory());report.addView(historyExport);content.addView(report);
